import sys,time,pickle,os,numpy as np,scipy.sparse as sp
from scipy.optimize import linprog
from sep import make,viol
from sep2 import separate
n=int(sys.argv[1]); target=float(sys.argv[2]); rounds=int(sys.argv[3]); tag=sys.argv[4] if len(sys.argv)>4 else ''
T,H,W,P,K,V,sig,pal,orbit_of,orbits,QE=make(n)
E=len(W); rows=np.concatenate([T,H]); cols=np.concatenate([P,P]); data=np.concatenate([np.ones(E),-np.ones(E)])
Aeq=sp.csr_matrix((data,(rows,cols)),shape=(V,K))
Ws=[format(int(w),'0%db'%n) for w in W]
issym=lambda s: s==s[::-1]
pref={}
for i,w in enumerate(Ws):
    for L in range(2,n):
        v=w[:L]
        if issym(v): pref.setdefault(v,{}); pref[v][P[i]]=pref[v].get(P[i],0)+1
Cv={v:sorted(p for p,c in dd.items() if c%2==1) for v,dd in pref.items()}
Cv={v:c for v,c in Cv.items() if c}
setcuts={}; prefcuts={}
fn='cuts3_n%d%s.pkl'%(n,tag)
if os.path.exists(fn):
    d=pickle.load(open(fn,'rb')); setcuts={(frozenset(S),tuple(F)):0 for S,F in d['set']}; prefcuts={(v,tuple(F)):0 for v,F in d['pref']}
elif os.path.exists('cuts2_n%d.pkl'%n) and 'noset' not in tag:
    for S,F in pickle.load(open('cuts2_n%d.pkl'%n,'rb'))['cuts']: setcuts[(frozenset(S),tuple(F))]=0
def rowsets():
    R=[];bb=[]
    for S,F in setcuts:
        row=np.zeros(K)
        for p,(a,b) in enumerate(QE):
            if (a in S)!=(b in S): row[p]=1
        for p in F: row[p]=-1
        R.append(-row); bb.append(-(1-len(F)))
    for v,F in prefcuts:
        row=np.zeros(K); row[Cv[v]]=1
        for p in F: row[p]=-1
        R.append(-row); bb.append(-(1-len(F)))
    return R,bb
def solve():
    R,bb=rowsets(); kw=dict(A_eq=Aeq,b_eq=np.zeros(V),bounds=(0,1),method='highs')
    if R: kw.update(A_ub=sp.csr_matrix(np.array(R)),b_ub=np.array(bb))
    res=linprog(-np.ones(K),**kw); return -res.fun,res.x
def save():
    pickle.dump({'n':n,'set':[(sorted(S),list(F)) for S,F in setcuts],'pref':[(v,list(F)) for v,F in prefcuts],'orbits':orbits,'QE':QE},open(fn,'wb'))
t0=time.time()
for rnd in range(rounds):
    val,y=solve()
    print('round',rnd,'setcuts',len(setcuts),'prefcuts',len(prefcuts),'LP',round(val,6),'%.0fs'%(time.time()-t0),flush=True)
    if val<target-1e-7: print('TARGET REACHED'); break
    newp=[]
    for v,C in Cv.items():
        yy=[y[p] for p in C]; val_=viol(yy)
        if val_<1-1e-7:
            F=[p for p in C if y[p]>0.5]
            if len(F)%2==0:
                q=min(C,key=lambda p:abs(1-2*y[p])); F=sorted(set(F)^{q})
            if (v,tuple(F)) not in prefcuts: newp.append((v,tuple(F)))
    news=[] if 'noset' in tag else [(S,F) for (w,S,F) in separate(QE,y,len(orbits)) if (S,F) not in setcuts]
    print('   new prefix cuts',len(newp),'new set cuts',len(news),flush=True)
    if not newp and not news: print('no violated parity cut of either family'); break
    for k in newp: prefcuts[k]=0
    for k in news: setcuts[k]=0
    if rnd%5==4: save()
save()
