import sys,numpy as np
from collections import deque
from gprime import build
def run(n):
    T,H,W,pal=build(n); V=2<<(n-1)
    out=np.zeros(V,int); inn=np.zeros(V,int)
    np.add.at(out,T,1); np.add.at(inn,H,1)
    b=out-inn
    Splus=[v for v in range(V) if b[v]>0]; Sminus=[v for v in range(V) if b[v]<0]
    # reverse BFS from S- (distance to S-)
    radj=[[] for _ in range(V)]
    for t,h in zip(T,H): radj[h].append(t)
    dist=[-1]*V; dq=deque()
    for v in Sminus: dist[v]=0; dq.append(v)
    while dq:
        h=dq.popleft()
        for t in radj[h]:
            if dist[t]<0: dist[t]=dist[h]+1; dq.append(t)
    B=sum(dist[v]*b[v] for v in Splus)
    return len(Splus),len(Sminus),max(b),min(b),B,sorted(dist[v] for v in Splus)
for n in range(int(sys.argv[1]),int(sys.argv[2])+1):
    sp_,sm,mx,mn,B,ds=run(n)
    from collections import Counter
    print(n,'|S+|',sp_,'|S-|',sm,'bmax',mx,'bmin',mn,'distsum',B,dict(Counter(ds)),flush=True)
