import sys,random,numpy as np
from ymodel import setup
def make(n):
    T,H,W,P,K,V,sig,pal=setup(n)
    # node orbits
    orbit_of=np.full(V,-1); orbits=[]
    for v in range(V):
        if (v>=(1<<(n-1)) and not pal[v-(1<<(n-1))]): continue
        if orbit_of[v]<0:
            s=sig(v); orbit_of[v]=orbit_of[s]=len(orbits); orbits.append((v,s))
    # Q edges: each y-orbit P -> (orbit of tail, orbit of head) using one representative arc
    rep={}
    for i in range(len(W)):
        if P[i] not in rep: rep[P[i]]=(orbit_of[T[i]],orbit_of[H[i]])
    QE=[rep[p] for p in range(K)]
    return T,H,W,P,K,V,sig,pal,orbit_of,orbits,QE
def viol(ycut):
    if not ycut: return 1.0
    s=sum(min(v,1-v) for v in ycut); big=sum(1 for v in ycut if v>0.5)
    if big%2==1: return s
    return s+min(abs(1-2*v) for v in ycut)
def search(QE,y,nQ,iters=2000,seed=0):
    rnd=random.Random(seed)
    adj=[[] for _ in range(nQ)]
    for p,(a,b) in enumerate(QE):
        adj[a].append(p); adj[b].append(p)
    best=None
    frac=[p for p in range(len(QE)) if 1e-6<y[p]<1-1e-6]
    for it in range(iters):
        p0=rnd.choice(frac); inS=set([QE[p0][0]])
        # grow
        def crossing(S):
            return [p for v in S for p in adj[v] if (QE[p][0] in S)!=(QE[p][1] in S)]
        cur=viol([y[p] for p in set(crossing(inS))])
        for step in range(60):
            cand=set()
            for v in inS:
                for p in adj[v]:
                    for u in QE[p]:
                        if u not in inS: cand.add(('add',u))
            for v in inS: cand.add(('rem',v))
            moves=[]
            for typ,u in cand:
                S2=set(inS); 
                if typ=='add': S2.add(u)
                else: S2.discard(u)
                if not S2: continue
                moves.append((viol([y[p] for p in set(crossing(S2))]),rnd.random(),S2))
