            moves.sort(key=lambda t:(t[0],t[1]))
            if moves[0][0]<=cur:
                cur=moves[0][0]; inS=moves[0][2]
            else: break
            if cur<1-1e-9: break
        if best is None or cur<best[0]: best=(cur,set(inS))
        if cur<1-1e-9: return best
    return best
if __name__=='__main__':
    from ymodel import solve
