# Exact separation of parity cuts (S reversal-closed, F odd subset of crossing pairs) for given y (any values),
# restricted to cuts of weight < 1, via subdivision (T-odd cut) + contraction of weight>=1 edges + Gomory-Hu per component.
import networkx as nx
from fractions import Fraction
def separate(QE,y,nQ,eps=1e-9,maxcuts=50):
    E=[(p,a,b) for p,(a,b) in enumerate(QE) if a!=b]
    N=nQ+len(E)
    par=list(range(N))
    def f(x):
        while par[x]!=x: par[x]=par[par[x]]; x=par[x]
        return x
    t=[0]*N; edges=[]
    for k,(p,a,b) in enumerate(E):
        m=nQ+k; t[m]^=1; t[b]^=1
        for (u,v,w) in ((a,m,y[p]),(m,b,1-y[p])):
            if w>=1-eps: par[f(u)]=f(v)
            elif w>eps: edges.append((u,v,w))
    G=nx.Graph()
    tp={}
    for x in range(N):
        r=f(x); tp[r]=tp.get(r,0)^t[x]
    for u,v,w in edges:
        a,b=f(u),f(v)
        if a==b: continue
        if G.has_edge(a,b): G[a][b]['capacity']+=w
        else: G.add_edge(a,b,capacity=w)
    found=[]
    # isolated supernodes with odd parity -> weight-0 violated cut
    roots=set(f(x) for x in range(N))
    for r in roots:
        if r not in G and tp[r]==1: found.append((0.0,{r}))
    for comp in nx.connected_components(G):
        par_c=sum(tp[r] for r in comp)%2
        if par_c==1: found.append((0.0,set(comp))); continue
        H=G.subgraph(comp).copy()
        if H.number_of_nodes()<2: continue
        GH=nx.gomory_hu_tree(H)
        for u,v,d in list(GH.edges(data=True)):
            if d['weight']<1-1e-7:
                GH2=GH.copy(); GH2.remove_edge(u,v)
                side=nx.node_connected_component(GH2,u)
                if sum(tp[r] for r in side)%2==1:
                    found.append((d['weight'],set(side)))
    found.sort(key=lambda z:z[0])
    out=[]
    for wt,side in found[:maxcuts]:
        Sp=set(x for x in range(N) if f(x) in side)
        S=set(x for x in Sp if x<nQ)
        F=[]
        cr=[]
        for k,(p,a,b) in enumerate(E):
            if (a in S)!=(b in S):
                cr.append(p); m=nQ+k
                # cost paid 1-y iff edge (m,b) cut
                if (m in Sp)!=(b in Sp): F.append(p)
        if len(F)%2==1 and S: out.append((wt,frozenset(S),tuple(sorted(F))))
    return out
