#!/usr/bin/env python3
# theory-B verify_lp.py (pure Python, exact integers). For each n: build G'_n, compute a min-cost transport R
# (successive shortest paths, SPFA) and a dual potential pi, then VERIFY independently:
#  (1) G'_n minus R is balanced (so 2*LP_cut >= E_n-|R| by Theorem 1),
#  (2) Phi(pi) = sum_{arcs e of G'_n} min(1, pi(tail e) - pi(head e)) equals |R|  (weak duality: D_n >= Phi(pi)),
# hence D_n = |R| and LP_cut(n) = (E_n - |R|)/2 exactly.  Also checks b(v) = [v=uc] - [v=cu] (u in Pal(n-2)).
import sys
from collections import deque
def rev(s): return s[::-1]
def gprime(n):
    m=n-1; arcs=[]
    for i in range(2**n):
        w=format(i,'0%db'%n)
        if w==rev(w): continue
        t,h=w[:-1],w[1:]
        tn = (t+('A' if w[-1]=='0' else 'B')) if t==rev(t) else t
        hn = (h+('A' if w[0]=='1' else 'B')) if h==rev(h) else h
        arcs.append((tn,hn,w))
    return arcs
def run(n):
    arcs=gprime(n); E=len(arcs)
    nodes=sorted(set([a for a,_,_ in arcs]+[b for _,b,_ in arcs]))
    bal={v:0 for v in nodes}
    for t,h,_ in arcs: bal[t]+=1; bal[h]-=1
    # check imbalance formula
    m=n-1; pal2=[format(i,'0%db'%(n-2)) for i in range(2**(n-2))]; pal2=[u for u in pal2 if u==rev(u)]
    pred={}
    for u in pal2:
        for c in '01':
            for v,s in ((u+c,1),(c+u,-1)):
                if v==rev(v):  # constant node: split copies
                    v = v+('B' if (s==1)==(c=='0') else 'A')
                pred[v]=pred.get(v,0)+s
    assert all(bal[v]==pred.get(v,0) for v in nodes), 'imbalance formula mismatch'
    # min-cost transport by SSP on residual graph with super source/sink
    idx={v:i for i,v in enumerate(nodes)}; N=len(nodes)+2; S=N-2; T=N-1
    to=[];cap=[];cost=[];adj=[[] for _ in range(N)]
    def add(u,v,c,w):
        adj[u].append(len(to)); to.append(v); cap.append(c); cost.append(w)
        adj[v].append(len(to)); to.append(u); cap.append(0); cost.append(-w)
    for t,h,_ in arcs: add(idx[t],idx[h],1,1)
    for v in nodes:
        if bal[v]>0: add(S,idx[v],bal[v],0)
        if bal[v]<0: add(idx[v],T,-bal[v],0)
    total=0
    while True:
        INF=10**9; d=[INF]*N; inq=[False]*N; pe=[-1]*N; d[S]=0; q=deque([S])
        while q:
            u=q.popleft(); inq[u]=False
            for e in adj[u]:
                if cap[e]>0 and d[u]+cost[e]<d[to[e]]:
                    d[to[e]]=d[u]+cost[e]; pe[to[e]]=e
                    if not inq[to[e]]: inq[to[e]]=True; q.append(to[e])
        if d[T]>=INF: break
        v=T
        while v!=S:
            e=pe[v]; cap[e]-=1; cap[e^1]+=1; v=to[e^1]
        total+=d[T]
    # R = arcs carrying flow
    R=set(k for k in range(len(arcs)) if cap[2*k]==0)
    # final potentials: shortest distances from S in residual graph (Bellman-Ford from S, unreachable -> large)
    d=[0]*N  # start all 0 = virtual source to every node
    changed=True; it=0
    while changed:
        changed=False; it+=1; assert it<=N+2, 'negative cycle'
        for u in range(N):
            for e in adj[u]:
                if cap[e]>0 and d[u]+cost[e]<d[to[e]]: d[to[e]]=d[u]+cost[e]; changed=True
    pi={v:-d[idx[v]] for v in nodes}   # potential
    # ---- independent verification ----
    bal2=dict(bal)
    for k in R:
        t,h,_=arcs[k]; bal2[t]-=1; bal2[h]+=1
    assert all(x==0 for x in bal2.values()), 'G minus R not balanced'
    Phi=sum(min(1,pi[t]-pi[h]) for t,h,_ in arcs)
    assert Phi==len(R), ('dual mismatch',Phi,len(R))
    En=2**n-2**((n+1)//2); assert En==E
    return E,len(R),Phi
if __name__=='__main__':
    for n in range(int(sys.argv[1]),int(sys.argv[2])+1):
        E,D,Phi=run(n)
        print('n=%d E_n=%d |R|=%d Phi(pi)=%d => D_n=%d, 2*LP_cut=%d, LP_cut=%s VERIFIED'%(n,E,D,Phi,D,E-D,(E-D)/2 if (E-D)%2 else (E-D)//2),flush=True)
