/* bf283.c -- independent exhaustive check for (a,n,d)=(2,8,3) upcycles, N=32.
   ASSUMES the published lemma (Chen-Kitaev-Muetze-Sun 2017, Lemma 14): diamonds are n-periodic,
   so the diamond set is {p : p mod 8 in S} for some S subset of Z_8 with |S| = 3 (d = 3).
   Enumerates all C(8,3)=56 sets S and all 2^20 letter assignments; a candidate is an upcycle iff
   no word of {0,1}^8 is covered twice (32 windows x 8 covered words = 256 = 2^8, so no double
   cover <=> exact cover). Prints the number of upcycles found per S and in total. */
#include <stdio.h>
#include <string.h>
int main(void){
  long total=0, tested=0;
  for(int S=0;S<256;S++){
    if(__builtin_popcount(S)!=3) continue;
    int dia[32], lpos[32], nl=0;
    for(int p=0;p<32;p++){ dia[p]=(S>>(p%8))&1; if(!dia[p]) lpos[nl++]=p; }
    /* nl == 20 */
    long found=0;
    for(long x=0;x<(1L<<nl);x++){
      int val[32]; for(int p=0;p<32;p++) val[p]=0;
      for(int k=0;k<nl;k++) val[lpos[k]]=(x>>k)&1;
      unsigned char seen[256]; memset(seen,0,256);
      int ok=1;
      for(int i=0;i<32 && ok;i++){
        int fm=0, fv=0; /* fixed-bit mask and values of window i; bit j = position i+j */
        for(int j=0;j<8;j++){ int p=(i+j)%32; if(!dia[p]){ fm|=1<<j; fv|=val[p]<<j; } }
        for(int w=0;w<256;w++) if((w&fm)==fv){ if(seen[w]){ok=0;break;} seen[w]=1; }
      }
      tested++;
      if(ok){ found++; if(found<=3){ printf("S=%02x upcycle: ",S); for(int p=0;p<32;p++) putchar(dia[p]?'*':'0'+val[p]); putchar('\n'); } }
    }
    printf("S=%02x (diamond residues", S); for(int r=0;r<8;r++) if((S>>r)&1) printf(" %d",r); printf(") upcycles=%ld\n", found);
    total+=found;
  }
  printf("tested=%ld total_upcycles=%ld\n", tested, total);
  return 0;
}
