"""genq.py a n N [--nonper | --per] : append to gen.py's CNF (stdin) aux D(p) <-> (no letter at p) and EITHER
 --per    : D(p) <-> D(p+n) for all p   (diamonds n-periodic), OR
 --nonper : OR_p E(p) with E(p) -> (D(p) xor D(p+n))  (diamonds NOT n-periodic).
Case split: F unsat <=> (F & per) unsat and (F & nonper) unsat. No published lemma is assumed."""
import sys
a, n, N = map(int, sys.argv[1:4]); mode = sys.argv[4]
lines = sys.stdin.read().splitlines()
hdr = [l for l in lines if l.startswith('p ')][0].split(); nv, nc = int(hdr[2]), int(hdr[3])
body = [l for l in lines if not l.startswith(('p', 'c'))]
def L(p, c): return 1 + (p % N)*a + c
def D(p): return nv + 1 + (p % N)
def E(p): return nv + N + 1 + (p % N)
cl = []
for p in range(N):
    for c in range(a): cl.append([-D(p), -L(p, c)])
    cl.append([D(p)] + [L(p, c) for c in range(a)])
if mode == '--per':
    for p in range(N): cl.append([-D(p), D(p+n)]); cl.append([D(p), -D(p+n)])
    extra = N
elif mode == '--nonper':
    for p in range(N): cl.append([-E(p), D(p), D(p+n)]); cl.append([-E(p), -D(p), -D(p+n)])
    cl.append([E(p) for p in range(N)]); extra = 2*N
else: raise SystemExit('mode')
print(f"c genq {mode}\np cnf {nv+extra} {nc+len(cl)}")
print('\n'.join(body)); print('\n'.join(' '.join(map(str, c)) + ' 0' for c in cl))
