import json
from fractions import Fraction
def rev(s): return s[::-1]
def bits(i,n): return format(i,'0%db'%n)
def words(n): return [bits(i,n) for i in range(2**n)]
def nonpal(n): return [w for w in words(n) if w!=rev(w)]
def pairkey(w): return min(w,rev(w))
def load(path):
    d=json.load(open(path)); return d
def crossing_pairs(S,n):
    S=set(S); cr={}
    for w in words(n):
        if w[:-1] in S and w[1:] not in S:
            cr[pairkey(w)]=1
    return set(cr)
def check_struct(d):
    n=d['n']; errs=[]
    if d['format']!='os-parity-cert-v2': errs.append('format')
    if len(d['z'])!=len(d['cuts']): errs.append('len z')
    for k,(c,z) in enumerate(zip(d['cuts'],d['z'])):
        S=c['S']; F=c['F']
        if any(len(s)!=n-1 or set(s)-set('01') for s in S): errs.append(f'cut{k} S bad strings')
        if any(len(w)!=n or set(w)-set('01') for w in F): errs.append(f'cut{k} F bad strings')
        if len(set(S))!=len(S): errs.append(f'cut{k} S dup')
        if set(rev(s) for s in S)!=set(S): errs.append(f'cut{k} S not reversal closed')
        Fk=[pairkey(w) for w in F]
        if len(set(Fk))!=len(Fk): errs.append(f'cut{k} F duplicate pairs')
        if any(w==rev(w) for w in F): errs.append(f'cut{k} F palindromic')
        cr=crossing_pairs(S,n)
        if not set(Fk)<=cr: errs.append(f'cut{k} F not subset Cr: {sorted(set(Fk)-cr)}')
        if len(set(Fk))%2!=1: errs.append(f'cut{k} |F| even')
        if Fraction(z)<0: errs.append(f'cut{k} z<0')
    return errs
