    for i, j, v in zip(Ac.row, Ac.col, Ac.data): colsU[j].append((i, int(v)))
    for i, j, v in zip(Ec.row, Ec.col, Ec.data): colsE[j].append((i, int(v)))
    st = {'lps': 0, 'leaves': 0, 't0': time.time()}

    def lp(fix):
        lb = np.zeros(len(arcs)); ub = np.ones(len(arcs))
        for i, v in fix.items(): lb[i] = ub[i] = v
        st['lps'] += 1
        return linprog(-np.ones(len(arcs)), A_ub=A_ub, b_ub=np.ones(A_ub.shape[0]), A_eq=A_eq,
                       b_eq=np.zeros(A_eq.shape[0]), bounds=np.column_stack([lb, ub]), method='highs')

    def bound(y, u, fix):
        b = sum(y, F(0))
        for j in range(len(arcs)):
            rj = 1 - sum((y[i] * c for i, c in colsU[j]), F(0)) - sum((u[i] * c for i, c in colsE[j]), F(0))
            if j in fix: b += rj * fix[j]
            elif rj > 0: b += rj
        return b

    def tryleaf(r, fix):
        if r.status != 0 or -r.fun >= T - 1e-7: return None
        for md in maxden_list:
            y = [max(F(0), F(-v).limit_denominator(md)) for v in r.ineqlin.marginals]
            u = [F(-v).limit_denominator(md) for v in r.eqlin.marginals]
            b = bound(y, u, fix)
            if b < T:
                return {"y": {ul[i]: str(v) for i, v in enumerate(y) if v},
                        "u": {el[i]: str(v) for i, v in enumerate(u) if v}, "bound": str(b)}
        return None

    def rec(fix, r, depth):
        if r is None: r = lp(fix)
        if r.status == 2: raise RuntimeError('infeasible box: Farkas not implemented')
        lf = tryleaf(r, fix)
        if lf is not None:
            st['leaves'] += 1
