{"file_path":"/home/agent/work/ccheck/root_bf.c","content":"/* Root's independent exhaustive search (no SAT, no symmetry breaking): cyclic partial words u of length N=32 over {0,1,D}
   whose diamond set is 8-periodic with residue set S (|S| = 3, all C(8,3)=56 choices), letters free (2^20 choices),
   such that the 32 windows of length 8 cover every word of {0,1}^8 exactly once (each window covers 2^3 = 8 words).
   Backtracking over letter positions in order 0..31; a window is checked as soon as its 8 positions are all assigned
   (window i uses positions i..i+7 mod 32; windows wrapping past 31 are checked at the end).
   Calibration: with N=8, n=4, |S|=1 (the (2,4,1) case) it must find exactly the known solutions (paper Example 8.5: 16). */
#include <stdio.h>
#include <string.h>
#ifndef NN
#define NN 8
#endif
#ifndef LEN
#define LEN 32
#endif
#ifndef DD
#define DD 3
#endif
static int isd[LEN], val[LEN], cov[1 << NN];
static long long found = 0, nodes = 0;
static int add_window(int i, int sgn) { /* add (sgn=+1) or remove (-1) coverage of window i; return 0 on conflict when adding */
  int dpos[NN], nd = 0, base = 0;
  for (int k = 0; k < NN; k++) { int p = (i + k) % LEN; if (isd[p]) dpos[nd++] = k; else base |= val[p] << (NN - 1 - k); }
  int ok = 1;
  for (int m = 0; m < (1 << nd); m++) {
    int w = base;
    for (int t = 0; t < nd; t++) if (m >> t & 1) w |= 1 << (NN - 1 - dpos[t]);
    if (sgn > 0) { if (cov[w]) ok = 0; cov[w]++; } else cov[w]--;
  }
  return ok;
}
static void rec(int p) {
  nodes++;
  if (p == LEN) { /* check wrapping windows i = LEN-NN+1 .. LEN-1 */
    int ok = 1, i;
    for (i = LEN - NN + 1; i < LEN; i++) if (!add_window(i, +1)) { ok = 0; i++; break; }
    if (ok) found++;
    for (int j = LEN - NN + 1; j < i; j++) add_window(j, -1);
    return;
  }
  int vals = isd[p] ? 1 : 2;
  for (int v = 0; v < vals; v++) {
    val[p] = isd[p] ? 0 : v;
    int i = p - NN + 1; /* window ending at p (non-wrapping) */
    if (i >= 0) { if (add_window(i, +1)) rec(p + 1); add_window(i, -1); }
    else rec(p + 1);
  }
}
int main(void) {
  long long total = 0; int sets = 0;
  for (int s = 0; s < (1 << NN); s++) {
    if (__builtin_popcount(s) != DD) continue;
    sets++;
    for (int p = 0; p < LEN; p++) isd[p] = (s >> (p % NN)) & 1;
    memset(cov, 0, sizeof cov); found = 0;
    rec(0);
    total += found;
    if (found) printf("residue set %02x: %lld solutions\n", s, found);
  }
  printf("NN=%d LEN=%d DD=%d: residue sets=%d, total solutions=%lld, search nodes=%lld\n", NN, LEN, DD, sets, total, nodes);
  return 0;
}
"}

