{"file_path":"/home/agent/work/os/euler_witness.py","content":"# Arc set (list of n-bit words) -> if weakly connected & balanced: Euler circuit -> cyclic sequence; then scan.
import sys, json
sys.setrecursionlimit(1000000)
from scan_os import is_os

def to_sequence(words, n):
    out = {}
    for w in words: out.setdefault(w[:-1], []).append(w)
    indeg = {}
    for w in words: indeg[w[1:]] = indeg.get(w[1:], 0) + 1
    for v in set(list(out) + list(indeg)):
        assert len(out.get(v, [])) == indeg.get(v, 0), 'unbalanced at ' + v
    # weak connectivity
    adj = {}
    for w in words:
        a, b = w[:-1], w[1:]
        adj.setdefault(a, set()).add(b); adj.setdefault(b, set()).add(a)
    start = words[0][:-1]; seen = {start}; st = [start]
    while st:
        v = st.pop()
        for u in adj[v]:
            if u not in seen: seen.add(u); st.append(u)
    comps_ok = len(seen) == len(adj)
    if not comps_ok: return None, 'disconnected: %d of %d nodes reached' % (len(seen), len(adj))
    # Hierholzer (iterative)
    ptr = {v: list(ws) for v, ws in out.items()}
    stack = [(start, None)]; circ = []
    while stack:
        v, w_in = stack[-1]
        if ptr.get(v):
            w = ptr[v].pop(); stack.append((w[1:], w))
        else:
            stack.pop()
            if w_in is not None: circ.append(w_in)
    circ.reverse()
    assert len(circ) == len(words)
    s = ''.join(w[0] for w in circ)
    return s, 'ok'

if __name__ == '__main__':
    n = int(sys.argv[1]); words = json.load(open(sys.argv[2]))
    s, msg = to_sequence(words, n)
    print(msg)
    if s:
        print('n=%d L=%d %s' % (n, len(s), 'VALID' if is_os(s, n) else 'INVALID'))
        open(sys.argv[3], 'w').write(s + '\n')
