"""Independent orientable-sequence scanner + witness checks.
OS(n): cyclic binary s of length L; the L cyclic n-windows are pairwise distinct, none is a palindrome,
and no window's reversal is also a window."""
import hashlib, lzma, base64, re, sys

R = '/home/agent/work/native_ref/'


def scan(s, n):
    L = len(s)
    if L == 0 or set(s) - {'0', '1'}:
        return False, 'not a nonempty bit string'
    t = s * ((n + L - 1) // L + 1)
    wins = [t[i:i + n] for i in range(L)]
    seen = set()
    for i, w in enumerate(wins):
        if w == w[::-1]:
            return False, 'palindromic window %s at %d' % (w, i)
        if w in seen:
            return False, 'repeated window %s at %d' % (w, i)
        seen.add(w)
    for i, w in enumerate(wins):
        if w[::-1] in seen:
            return False, 'window %s at %d and its reversal both occur' % (w, i)
    return True, 'VALID OS(%d) period %d' % (n, L)


def witnesses():
    out = []
    # w10 from certificates-a.md: the 426-bit line after the 'w10 (' header
    lines = open(R + 'certificates-a.md').read().split('\n')
    i = next(k for k, l in enumerate(lines) if l.startswith('w10 ('))
    stated = re.search(r'([0-9a-f]{64})', lines[i]).group(1)
    w10 = lines[i + 1].strip()
    out.append(('w10 (certificates-a.md)', 10, 426, w10, stated, 'sha256(bits+\\n)'))
    for nm, n, L in (('w11cg.txt', 11, 860), ('w13cg.txt', 13, 3728)):
        raw = open(R + 'out/payloads/' + nm, 'rb').read()
        out.append((nm + ' (cg-certificates.md)', n, L, raw.decode().strip(), hashlib.sha256(raw).hexdigest(), 'file hash checked at extraction'))
    for line in open(R + 'witness_hex_11_14_system2.txt'):
        n, L, h, hx = line.split()
        n, L = int(n), int(L)
        s = bin(int(hx, 16))[2:].zfill(4 * len(hx))[-L:]
        out.append(('hex n=%d' % n, n, L, s, h, 'sha256(bits)'))
    return out


if __name__ == '__main__':
