# referee-A independent branch-and-bound certificate generator (own model common.rows, own branching rule:
# most-fractional variable, ties by word order; depth-first). Output os-palcut-cert-v1 (strict format, no extra keys),
# then verified by refcheck.py (strict). Untrusted generator; soundness rests on refcheck.py.
import sys, json, time, math
import numpy as np
from fractions import Fraction
from scipy.optimize import linprog
from scipy.sparse import lil_matrix
from common import *

def setup(n):
    W = words(n); idx = {w: i for i, w in enumerate(W)}
    R = rows(n)
    P = [k for k in R if k[0] == 'P']
    E = [k for k in R if k[0] in 'BC' and R[k][0]]
    Aub = lil_matrix((len(P), len(W))); Aeq = lil_matrix((len(E), len(W)))
    for r, k in enumerate(P):
        for w, a in R[k][0].items(): Aub[r, idx[w]] = a
    for r, k in enumerate(E):
        for w, a in R[k][0].items(): Aeq[r, idx[w]] = a
    cols = [[] for _ in W]
    for r, k in enumerate(P):
        for w, a in R[k][0].items(): cols[idx[w]].append(('P', r, a))
    for r, k in enumerate(E):
        for w, a in R[k][0].items(): cols[idx[w]].append(('E', r, a))
    return W, idx, R, P, E, Aub.tocsr(), Aeq.tocsr(), cols

def exact_bound(y, u, fix, cols, nW):
    b = sum(y, Fraction(0))
    for j in range(nW):
        r = Fraction(1)
        for t, i, a in cols[j]:
            r -= (y[i] if t == 'P' else u[i]) * a
        if j in fix: b += r * fix[j]
        elif r > 0: b += r
    return b

def bnb(n, T, maxleaves=2000):
    W, idx, R, P, E, Aub, Aeq, cols = setup(n)
    st = {'lp': 0, 'leaves': 0}
    def rec(fix, depth):
        lb = np.zeros(len(W)); ub = np.ones(len(W))
        for j, v in fix.items(): lb[j] = ub[j] = v
        res = linprog(-np.ones(len(W)), A_ub=Aub, b_ub=np.ones(len(P)), A_eq=Aeq, b_eq=np.zeros(len(E)),
                      bounds=np.column_stack([lb, ub]), method='highs')
        st['lp'] += 1
        if res.status != 0: raise RuntimeError('LP status %d at depth %d' % (res.status, depth))
        for den in (1, 2, 4, 8, 64, 1024, 10**6):
            y = [max(Fraction(0), Fraction(-m).limit_denominator(den)) for m in res.ineqlin.marginals]
            u = [Fraction(-m).limit_denominator(den) for m in res.eqlin.marginals]
            b = exact_bound(y, u, fix, cols, len(W))
            if b < T:
                st['leaves'] += 1
                if st['leaves'] > maxleaves: raise RuntimeError('too many leaves')
                return {'y': {P[i]: str(q) for i, q in enumerate(y) if q}, 'u': {E[i]: str(q) for i, q in enumerate(u) if q}, 'bound': str(b)}
        x = res.x
        cand = sorted((abs(x[j] - 0.5), W[j], j) for j in range(len(W)) if j not in fix and 1e-6 < x[j] < 1 - 1e-6)
        if not cand: raise RuntimeError('integral LP optimum %.3f >= T at depth %d' % (-res.fun, depth))
        j = cand[0][2]
        return {'split': W[j], 'x0': rec({**fix, j: 0}, depth + 1), 'x1': rec({**fix, j: 1}, depth + 1)}
    t0 = time.time()
    tree = rec({}, 0)
    return {'format': 'os-palcut-cert-v1', 'n': n, 'T': T, 'tree': tree}, st, time.time() - t0

if __name__ == '__main__':
    n, T = int(sys.argv[1]), int(sys.argv[2])
    c, st, dt = bnb(n, T)
    fn = 'my_bnb_n%d_T%d.json' % (n, T)
    json.dump(c, open(fn, 'w'), sort_keys=True, separators=(',', ':'))
    print('n=%d T=%d %s time %.1fs -> %s' % (n, T, st, dt, fn), flush=True)
