# referee-A common definitions (independent; written from TASK-A spec only)
from fractions import Fraction
from itertools import product

def rev(s): return s[::-1]
def ispal(s): return s == s[::-1]

def words(n):
    """all non-palindromic n-bit words, as strings"""
    return [''.join(t) for t in product('01', repeat=n) if not ispal(''.join(t))]

def nodes(n):
    return [''.join(t) for t in product('01', repeat=n-1)]

def palnodes(n):
    return [v for v in nodes(n) if ispal(v)]

def pairs(n):
    """reverse pairs (lexmin, other) of non-palindromic words"""
    return sorted({tuple(sorted((w, rev(w)))) for w in words(n)})

def rows(n):
    """returns dict label -> (coef dict word->int, sense, rhs)
       P:<a>  x_a + x_{a^R} <= 1
       B:<v>  sum_out - sum_in = 0     (palindromic words dropped = count 0)
       C:<v>:<b> x_{vb} - x_{(1-b)v} = 0 for palindromic v (palindromic words dropped)"""
    W = set(words(n)); R = {}
    for a, b in pairs(n):
        R['P:' + a] = ({a: 1, b: 1}, '<=', 1)
    for v in nodes(n):
        c = {}
        for b in '01':
            w = v + b
            if w in W: c[w] = c.get(w, 0) + 1
            w = b + v
            if w in W: c[w] = c.get(w, 0) - 1
        c = {k: x for k, x in c.items() if x != 0}
        R['B:' + v] = (c, '=', 0)
    for v in palnodes(n):
        for b in '01':
            c = {}
            w1 = v + b; w2 = ('1' if b == '0' else '0') + v
            if w1 in W: c[w1] = c.get(w1, 0) + 1
            if w2 in W: c[w2] = c.get(w2, 0) - 1
            c = {k: x for k, x in c.items() if x != 0}
            R['C:%s:%s' % (v, b)] = (c, '=', 0)
    return R

def windows(s, n):
    L = len(s); t = s + s[:n-1]
    return [t[i:i+n] for i in range(L)]

def is_os(s, n):
    """cyclic binary s is an orientable sequence of order n: every window non-palindromic,
       windows pairwise distinct and no window equals the reverse of another (or itself)."""
    ws = windows(s, n)
    if len(ws) < 1: return False, 'empty'
    seen = set()
    for w in ws:
        if ispal(w): return False, 'palindromic window ' + w
        if w in seen: return False, 'repeated window ' + w
        seen.add(w)
    for w in ws:
        if rev(w) in seen: return False, 'reverse also present ' + w
    return True, 'ok'

def check_PBC(x, n):
    """x: set of words with value 1. returns list of violated row labels."""
    bad = []
    for lab, (c, sense, rhs) in rows(n).items():
        val = sum(k * (1 if w in x else 0) for w, k in c.items())
        if sense == '<=' and not val <= rhs: bad.append(lab)
        if sense == '=' and val != rhs: bad.append(lab)
    return bad
