# Phase 1(a): exhaustive falsification of the cut lemma.
#  part 1: all 0/1 x with (P),(B) for n=3..5 (3^#pairs enumeration), test (C)
#  part 2: all OS(n) cycles (every period) for n=3..7 by DFS, test (P),(B),(C) on window sets
import sys, time
from itertools import product
from common import *

def part1(n):
    P = pairs(n); R = rows(n)
    Crows = {k: v for k, v in R.items() if k[0] == 'C'}
    Brows = {k: v for k, v in R.items() if k[0] == 'B'}
    nsol = 0; nviol = 0; maxsum = 0
    for choice in product((0, 1, 2), repeat=len(P)):
        x = set()
        for (a, b), c in zip(P, choice):
            if c == 1: x.add(a)
            elif c == 2: x.add(b)
        ok = all(sum(k for w, k in c.items() if w in x) == 0 for c, _, _ in Brows.values())
        if not ok: continue
        nsol += 1; maxsum = max(maxsum, len(x))
        if any(sum(k for w, k in c.items() if w in x) != 0 for c, _, _ in Crows.values()):
            nviol += 1
            if nviol <= 3: print('  VIOLATION', n, sorted(x))
    print('part1 n=%d pairs=%d (P)(B)-solutions=%d violating(C)=%d max sum=%d' % (n, len(P), nsol, nviol, maxsum))

def part2(n, limit_time=600):
    W = set(words(n)); t0 = time.time()
    count = {}; nviol = 0; nbad = 0
    for w0 in sorted(W):
        start = w0[:-1]
        used = {w0}
        path = [w0]
        def dfs(node):
            nonlocal nviol, nbad
            if node == start:
                L = len(path)
                count[L] = count.get(L, 0) + 1
                x = set(path)
                bad = check_PBC(x, n)
                s = path[0][:-1][:0] + ''.join(p[0] for p in path)
                ok, why = is_os(s, n)
                if not ok: nbad += 1
                if bad:
                    nviol += 1
                    if nviol <= 3: print('  VIOLATION n=%d s=%s rows=%s' % (n, s, bad))
            for b in '01':
                w = node + b
                if w in W and w > w0 and w not in used and rev(w) not in used:
                    used.add(w); path.append(w)
                    dfs(w[1:])
                    path.pop(); used.discard(w)
        dfs(w0[1:])
    tot = sum(count.values())
    print('part2 n=%d cycles=%d by period=%s max period=%s violating(P/B/C)=%d scanner-rejects=%d time=%.1fs' % (
        n, tot, dict(sorted(count.items())), max(count) if count else 0, nviol, nbad, time.time() - t0))

if __name__ == '__main__':
    for n in (3, 4, 5): part1(n)
    for n in (3, 4, 5, 6, 7): part2(n)
